using A=JsonValue::Array;using O=JsonValue::Object;
JsonValue number(double x){if(std::isnan(x))return "NaN";if(std::isinf(x))return x<0?"-Infinity":"Infinity";if(x==0&&std::signbit(x))return "-0";return x;}
template<class T>JsonValue values(const T& source){A result;for(auto x:source)result.push_back(number(x));return result;}
JsonValue vector(const Vector3& v){return A{number(v.x),number(v.y),number(v.z)};}
JsonValue attribute(const std::shared_ptr<VertexAttribute>& v){if(!v)return nullptr;A array;const auto data=v->getArray();for(std::size_t i=0;i<data.size();++i)array.push_back(number(data.number(double(i))));return O{{"array",array},{"itemSize",number(v->getItemSize())},{"count",number(v->getCount())},{"version",number(v->getProperty("version").toNumber())}};}
