JsonValue material(const std::shared_ptr<Material>& m){if(!m)return nullptr;O out{{"type",m->type},{"vertexColors",m->vertexColors},{"toneMapped",m->toneMapped},{"depthTest",m->depthTest},{"depthWrite",m->depthWrite},{"transparent",m->transparent},{"opacity",number(m->opacity)}};if(const auto l=std::dynamic_pointer_cast<LineBasicMaterial>(m)){out["color"]=values(l->color.toArray());out["fog"]=l->fog;}if(const auto mesh=std::dynamic_pointer_cast<MeshBasicMaterial>(m)){out["color"]=values(mesh->color.toArray());out["fog"]=mesh->fog;out["wireframe"]=mesh->wireframe;}return out;}
JsonValue state(const Object3D& o){A children;for(const auto& c:o.children)children.push_back(state(*c));O out{{"type",o.type},{"position",vector(o.position)},{"scale",vector(o.scale)},{"quaternion",values(o.quaternion.toArray())},{"matrix",values(o.matrix.toArray())},{"matrixWorld",values(o.matrixWorld.toArray())},{"matrixAutoUpdate",o.matrixAutoUpdate},{"matrixWorldNeedsUpdate",o.matrixWorldNeedsUpdate},{"children",children}};if(const auto* l=dynamic_cast<const Line*>(&o)){out["geometry"]=geometry(l->geometry);out["material"]=material(l->material);}if(const auto* m=dynamic_cast<const Mesh*>(&o)){out["geometry"]=geometry(m->geometry);out["material"]=material(m->material);}return out;}
std::vector<std::shared_ptr<Object3D>> defaults(){return {std::make_shared<ArrowHelper>(),std::make_shared<AxesHelper>(),std::make_shared<Box3Helper>(std::make_shared<Box3>()),std::make_shared<BoxHelper>(),std::make_shared<CameraHelper>(std::make_shared<PerspectiveCamera>()),std::make_shared<DirectionalLightHelper>(std::make_shared<DirectionalLight>()),std::make_shared<GridHelper>(),std::make_shared<HemisphereLightHelper>(std::make_shared<HemisphereLight>()),std::make_shared<PlaneHelper>(std::make_shared<Plane>()),std::make_shared<PointLightHelper>(std::make_shared<PointLight>()),std::make_shared<PolarGridHelper>(),std::make_shared<SkeletonHelper>(std::make_shared<Bone>()),std::make_shared<SpotLightHelper>(std::make_shared<SpotLight>())};}
