JsonValue planeCase(int mode){auto plane=std::make_shared<Plane>(Vector3(1,2,3),-2);if(mode==1)plane->normal.set(0,0,0);if(mode==2)plane->constant=0;if(mode==3)plane->normal.set(0,1,0);auto helper=std::make_shared<PlaneHelper>(plane,3,"#ff8000");auto parent=std::make_shared<Object3D>();if(mode==4){parent->position.set(3,4,5);parent->rotation.set(.2,.3,.4);parent->scale.set(2,3,4);parent->add(helper);parent->updateMatrixWorld();}helper->updateMatrixWorld(true);return state(*helper);}
