JsonValue skeletonCase(int mode){auto root=std::make_shared<Object3D>();auto a=std::make_shared<Bone>(),b=std::make_shared<Bone>(),c=std::make_shared<Bone>();root->position.set(3,4,5);root->rotation.set(.1,.2,.3);root->add(a);a->add(b);b->add(c);a->position.set(1,2,3);b->position.set(2,0,1);c->position.set(-1,2,0);root->updateMatrixWorld();SkeletonHelper helper(root);if(mode==1){b->position.set(-4,2,0);root->updateMatrixWorld();}if(mode==2)b->remove(c);if(mode==3){helper.bones={c,b,a};helper.setColors(Color(.2,.3,.4),Color(.7,.8,.9));}helper.updateMatrixWorld(true);A names;for(const auto& bone:helper.bones)names.push_back(bone==a?"a":bone==b?"b":"c");return O{{"helper",state(helper)},{"bones",names}};}
JsonValue lightCase(int kind,int mode){auto parent=std::make_shared<Object3D>();parent->position.set(3,4,5);parent->rotation.set(.2,-.3,.4);parent->scale.set(2,3,4);auto helperParent=std::make_shared<Object3D>();helperParent->position.set(-2,1,3);helperParent->rotation.set(.1,.4,-.2);HelperColor color;if(mode==1)color="#ff8000";if(mode==2)color=Color(.1,.2,.3);if(mode==3)color=JSValue(nullptr);std::shared_ptr<Object3D> helper;std::shared_ptr<Light> light;
 if(kind==0){auto l=std::make_shared<PointLight>(Color(0x22aaff));light=l;auto h=std::make_shared<PointLightHelper>(l,2,color);helper=h;parent->add(l);l->position.set(1,2,3);helperParent->add(h);h->update();}
 if(kind==1){auto l=std::make_shared<DirectionalLight>(Color(0x22aaff));light=l;auto h=std::make_shared<DirectionalLightHelper>(l,2,color);helper=h;parent->add(l);l->position.set(1,2,3);l->target->position.set(-2,3,-4);helperParent->add(h);h->update();}
 if(kind==2){auto l=std::make_shared<HemisphereLight>(Color(0x22aaff),Color(0xaabb33));light=l;auto h=std::make_shared<HemisphereLightHelper>(l,2,color);helper=h;parent->add(l);l->position.set(1,2,3);helperParent->add(h);h->update();}
 if(kind==3){auto l=std::make_shared<SpotLight>(Color(0x22aaff));light=l;auto h=std::make_shared<SpotLightHelper>(l,color);helper=h;parent->add(l);l->position.set(1,2,3);l->target->position.set(-2,3,-4);l->distance=mode==0?0:mode==1?-10:mode==2?7:NAN;l->angle=.4;helperParent->add(h);h->update();}
 helper->updateMatrixWorld(true);return state(*helper);}
JsonValue disposeCase(std::shared_ptr<Object3D> helper){A events;std::vector<const void*> seen;const auto hook=[&](EventDispatcher* resource,const std::string& label){if(std::find(seen.begin(),seen.end(),resource)!=seen.end())return;seen.push_back(resource);resource->addEventListener("dispose",[&,label](Event&){events.push_back(label);});};std::function<void(Object3D&,std::string)> visit=[&](Object3D& o,std::string path){hook(&o,path);if(auto* line=dynamic_cast<Line*>(&o)){hook(line->geometry.get(),path+".geometry");hook(line->material.get(),path+".material");}if(auto* mesh=dynamic_cast<Mesh*>(&o)){hook(mesh->geometry.get(),path+".geometry");hook(mesh->material.get(),path+".material");}for(std::size_t i=0;i<o.children.size();++i)visit(*o.children[i],path+"."+std::to_string(i));};visit(*helper,"helper");helper->dispose();return O{{"type",helper->type},{"events",events}};}
int main(){try {A result;for(const auto& helper:defaults())result.push_back(O{{"kind","default"},{"state",state(*helper)}});for(double size:{-2.,0.,.5,1.}){AxesHelper helper(size);helper.setColors(0xff8000,"#80ff00",Color(.1,.2,.3));result.push_back(O{{"kind","axes"},{"state",state(helper)}});}for(double divisions:{-1.,0.,1.,3.,4.,4.5,double(NAN)}){GridHelper helper(3.5,divisions);result.push_back(O{{"kind","grid"},{"state",state(helper)}});}for(int mode=0;mode<7;++mode){PolarGridHelper helper(mode==1?-2:3,mode==2?0:mode==3?2.5:4,mode==4?0:mode==5?2.5:3,mode==6?3.5:8);result.push_back(O{{"kind","polar"},{"state",state(helper)}});}for(const Vector3& dir:{Vector3(0,1,0),Vector3(0,-1,0),Vector3(1,0,0),Vector3(1,2,3),Vector3(0,0,0),Vector3(.3,.99999,.2)}){ArrowHelper helper(dir,{1,2,3},-2,"#ff8000");helper.setLength(3,.7,.3);result.push_back(O{{"kind","arrow"},{"state",state(helper)}});}for(int mode=0;mode<4;++mode)result.push_back(O{{"kind","box"},{"state",boxCase(mode)}});for(int mode=0;mode<5;++mode)result.push_back(O{{"kind","plane"},{"state",planeCase(mode)}});for(int mode=0;mode<15;++mode)result.push_back(O{{"kind","camera"},{"state",cameraCase(mode)}});for(int mode=0;mode<4;++mode)result.push_back(O{{"kind","skeleton"},{"state",skeletonCase(mode)}});for(int kind=0;kind<4;++kind)for(int mode=0;mode<4;++mode)result.push_back(O{{"kind","light"},{"state",lightCase(kind,mode)}});for(const auto& helper:defaults()){try{const auto copy=helper->clone();result.push_back(O{{"kind","clone"},{"type",helper->type},{"state",state(*copy)},{"error",""}});}catch(const JSTypeError&){result.push_back(O{{"kind","clone"},{"type",helper->type},{"error","TypeError"}});}}for(auto& helper:defaults())result.push_back(O{{"kind","dispose"},{"state",disposeCase(helper)}});std::cout<<JsonValue(result).dump()<<'\n';}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
